arguments.content:
body { margin: 0; font-family: sans-serif; color: #ffffff; }
.hud { position: absolute; top: 12px; right: 16px; display: flex; gap: 16px; padding: 8px 14px;
       background-color: rgba(0, 0, 0, 0.55); border-radius: 8px; }
.score { font-size: 26px; color: #ffd166; }
.gems { font-size: 18px; }
.gems.all { color: #8fe388; }

:root { --accent: #f2a541; --panel: rgba(16, 22, 38, 0.88); --text: #f4f6fb; }
* { box-sizing: border-box; }
html { background: linear-gradient(160deg, #1d3557, #0b0c16 75%); }
body { margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
       font-family: sans-serif; color: var(--text); }
.menu { width: 420px; padding: 28px; display: flex; flex-direction: column; gap: 14px;
        background: var(--panel); border: 2px solid rgba(255, 255, 255, 0.15); border-radius: 14px; }
.title { margin: 0; font-size: 40px; text-align: center; color: var(--accent); }
.subtitle { margin: 0; text-align: center; opacity: 0.75; }
.btn { padding: 12px 16px; font-size: 20px; color: var(--text); border: 0; border-radius: 10px;
       background-color: #3a5a8c; }
.btn.primary { background-color: #e07a1f; }
.status { margin: 0; text-align: center; }
.status.ready { color: #8fe388; }
.ticks { margin: 0; text-align: right; font-size: 14px; opacity: 0.6; }
